import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Definizione di probabilità soggettiva","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lcfb.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lcfb.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lcfb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="definizione-di-probabilita-soggettiva" tabindex="-1">Definizione di probabilità soggettiva <a class="header-anchor" href="#definizione-di-probabilita-soggettiva" aria-label="Permalink to “Definizione di probabilità soggettiva”">​</a></h1><p>Secondo la teoria soggettiva: <strong>la probabilità è la misura del grado di fiducia che un individuo coerente assegna al verificarsi di un dato evento in base alle sue conoscenze</strong>.</p><blockquote><p>Continuiamo come esempio con la nostra probabilità applicata al mondo del calcio</p></blockquote><p>Notare che l&#39;individuo deve essere coerente, cioè non deviato da passioni, ed inoltre deve avere delle conoscenze (tipo sapere quali sono i giocatori che scenderanno in campo e com&#39;è la loro forma fisica).</p><p>In pratica se attribuisco ad un evento la probabilità del <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>90</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">90\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">90%</span></span></span></span> devo essere disposto a pagare una somma di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>90</mn></mrow><annotation encoding="application/x-tex">90</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">90</span></span></span></span> per riceverne <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn></mrow><annotation encoding="application/x-tex">100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> in caso di evento che accade oppure di perdere tutto in caso di evento che non accade.</p><blockquote><p><strong>Esempio:</strong> se penso che le probabilità di vincita dell&#39;Inter nella partita Inter-Lazio siano del <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">70\\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">70%</span></span></span></span> devo essere disposto a puntare <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70</mn></mrow><annotation encoding="application/x-tex">70</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">70</span></span></span></span> euro sulla vincita dell&#39;Inter per riceverne <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn></mrow><annotation encoding="application/x-tex">100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> in caso di vittoria dell&#39;Inter e perdendo tutto in caso di sconfitta o pareggio della squadra.</p></blockquote><p>È fondamentale che il soggetto abbia il maggior numero di informazioni possibili e, tramite esse, sappia attribuire determinate probabilità a determinati eventi. In tal caso la probabilità soggettiva si può ritenere affidabile.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};